<template>
  <div :class="['w-7 h-7 rounded-lg flex items-center justify-center flex-shrink-0', wrap]">
    <ILucideArrowLeftRight v-if="kind === 'transfer'" class="h-4 w-4 text-blue-500" />
    <ILucideArrowDownLeft v-else-if="qty >= 0" class="h-4 w-4 text-green-600" />
    <ILucideArrowUpRight v-else class="h-4 w-4 text-red-500" />
  </div>
</template>

<script setup lang="ts">
import type { StockMovementKind } from "../stock.types";

const props = defineProps<{ kind: StockMovementKind; qty: number }>();

const wrap = computed(() => {
  if (props.kind === "transfer") return "bg-blue-50";
  return props.qty >= 0 ? "bg-green-50" : "bg-red-50";
});
</script>
