<template>
  <!-- :style="{
      backgroundImage: `linear-gradient(to bottom, transparent 25vh, var(--color-stock-bg) 30vh), linear-gradient(to right, var(--color-stock-bg) 0%, transparent 30%), url(${stockVisualAssets.blueprintBg})`,
    }" -->
  <F7Page
    class="page-stock bg-stock-bg bg-cover bg-center"
    infinite
    :infinite-distance="250"
    :infinite-preloader="hasMoreProducts"
    @infinite="handleInfinite"
  >
    <F7Navbar title="Stock" large :sliding="true">
      <template #nav-right>
        <div class="flex items-center gap-2 pr-3">
          <F7Link href="/stock/search/" icon-only class="!w-10 !h-10">
            <span
              class="glass-surface flex h-10 w-10 min-w-[40px] shrink-0 items-center justify-center rounded-[13px]"
            >
              <ILucideSearch class="h-[18px] w-[18px] text-ink-soft" />
            </span>
          </F7Link>
          <F7Link icon-only class="!w-10 !h-10">
            <span
              class="glass-surface flex h-10 w-10 min-w-[40px] shrink-0 items-center justify-center rounded-[13px]"
            >
              <ILucideScanLine class="h-[18px] w-[18px] text-ink-soft" />
            </span>
          </F7Link>
        </div>
      </template>
    </F7Navbar>

    <div class="relative mx-auto min-h-full overflow-hidden px-[18px] pb-[116px]">
      <div class="relative z-20 mb-8">
        <div class="relative z-20 grid w-[100%] grid-cols-2 gap-2 max-[430px]:gap-1.5">
          <StockMetricCard
            v-for="metric in metrics"
            :key="metric.label"
            :label="metric.label"
            :value="metric.value"
            :icon="metric.icon"
            :tone="metric.tone"
          />
        </div>
      </div>

      <div class="relative z-10 mb-3">
        <h2 class="m-0 text-[19px] font-[640] tracking-[-0.01em] leading-none text-[#3a4264]">
          Activities
        </h2>
      </div>

      <div class="relative z-10 mb-[22px] grid grid-cols-2 grid-rows-2 gap-2.5 max-[430px]:gap-2">
        <StockActionTile
          v-for="action in stockActionVisuals"
          :key="action.key"
          :label="action.label"
          :image="action.image"
        />
      </div>

      <section class="relative z-10 mb-3.5">
        <div class="mb-3.5">
          <h2 class="m-0 text-[19px] font-[640] tracking-[-0.01em] leading-none text-[#3a4264]">
            Products
          </h2>
        </div>

        <F7List
          v-if="paginatedProducts.length"
          virtual-list
          no-hairlines
          :virtual-list-params="vlParams"
          class="!my-0 !bg-transparent [&_ul]:!bg-transparent"
        >
          <ul>
            <li
              v-for="(item, index) in vlData.items"
              :key="item.ruid"
              class="!bg-transparent !pb-2"
              :style="`top: ${vlData.topPosition}px`"
              :virtual-list-index="vlData.fromIndex + index"
            >
              <StockNeedCard
                :name="item.name"
                :sku-label="item.sku ? `SKU ${item.sku}` : '—'"
                :state-label="productStateLabel(item.onHand)"
                :health="item.health"
                :image-src="productImageSrc(item.image)"
                @open="openProduct(item.ruid)"
              />
            </li>
          </ul>
        </F7List>
        <p v-else class="mx-0.5 mt-2.5 text-sm font-[540] text-[#657096]">No products found.</p>
      </section>
    </div>

    <StockProductSheet v-model:opened="sheetOpen" :product-ruid="selectedRuid" />
  </F7Page>
</template>

<script setup lang="ts">
import StockActionTile from "../components/StockActionTile.vue";
import StockMetricCard from "../components/StockMetricCard.vue";
import StockNeedCard from "../components/StockNeedCard.vue";
import StockProductSheet from "../components/StockProductSheet.vue";
import { useStockDashboard } from "../composables/useStockDashboard";
import { formatCompact, formatCount } from "../stock.format";
import type { StockNeedsActionItem } from "../stock.types";
import { productImageSrc, stockActionVisuals, stockVisualAssets } from "../stock.visuals";

const { overview, paginatedProducts, hasMoreProducts, loadMoreProducts } = useStockDashboard();

const sheetOpen = ref(false);
const selectedRuid = ref<string | null>(null);

const vlInstance = shallowRef<any>(null);
const vlData = ref<{
  items: StockNeedsActionItem[];
  topPosition: number;
  fromIndex: number;
  toIndex: number;
}>({ items: [], topPosition: 0, fromIndex: 0, toIndex: 0 });

function renderVl(vl: any, data: any) {
  vlInstance.value = vl;
  vlData.value = {
    items: data.items ?? [],
    topPosition: data.topPosition ?? 0,
    fromIndex: data.fromIndex ?? 0,
    toIndex: data.toIndex ?? 0,
  };
}

const vlParams = computed(() => ({
  items: paginatedProducts.value,
  renderExternal: renderVl,
  height: 92,
  rowsBefore: 10,
  rowsAfter: 10,
}));

watch(
  paginatedProducts,
  (next) => {
    vlInstance.value?.replaceAllItems(next);
  },
  { flush: "post" },
);

function handleInfinite() {
  if (!hasMoreProducts.value) return;
  loadMoreProducts();
}

const metrics = computed(
  () =>
    [
      {
        label: "Total SKUs",
        value: formatCount(overview.value.totalSkus),
        icon: "package",
        tone: "blue",
      },
      {
        label: "Low stock",
        value: formatCount(overview.value.lowStock),
        icon: "low",
        tone: "orange",
      },
      {
        label: "Out of stock",
        value: formatCount(overview.value.outOfStock),
        icon: "alert",
        tone: "red",
      },
      {
        label: "Stock value",
        value: `DZD ${formatCompact(overview.value.stockValue)}`,
        icon: "value",
        tone: "violet",
      },
    ] as const,
);

function productStateLabel(onHand: number) {
  if (onHand <= 0) return "Out of stock";
  return `${formatCompact(onHand)} units`;
}

function openProduct(ruid: string) {
  selectedRuid.value = ruid;
  sheetOpen.value = true;
}
</script>
