<template>
  <div
    class="flex min-w-0 flex-col justify-between gap-2 overflow-hidden rounded-[18px] border border-[rgba(222,230,244,0.86)] bg-[radial-gradient(circle_at_50%_8%,rgba(255,255,255,0.96),rgba(242,247,255,0.72)),rgba(255,255,255,0.74)] p-4 shadow-[0_18px_34px_rgba(32,58,112,0.09),inset_0_1px_0_rgba(255,255,255,0.95)]"
  >
    <div
      :class="[
        'flex h-10 w-10 shrink-0 items-center justify-center rounded-[12px] border',
        iconClass,
      ]"
    >
      <ILucidePackageCheck v-if="icon === 'package'" class="h-5 w-5" />
      <ILucideArrowDown v-else-if="icon === 'low'" class="h-5 w-5" />
      <ILucideCircleAlert v-else-if="icon === 'alert'" class="h-5 w-5" />
      <ILucideDiamond v-else class="h-5 w-5" />
    </div>
    <div class="flex min-w-0 flex-col gap-1">
      <h2
        class="whitespace-nowrap my-1 text-[22px] font-[660] leading-none tracking-[-0.01em] text-[#323a5e]"
      >
        {{ value }}
      </h2>
      <span class="truncate text-[12.5px] font-[520] leading-tight text-[#8895b3]">
        {{ label }}
      </span>
    </div>
  </div>
</template>

<script setup lang="ts">
const props = defineProps<{
  label: string;
  value: string;
  icon: "package" | "low" | "alert" | "value";
  tone: "blue" | "orange" | "red" | "violet";
}>();

const TONE: Record<string, string> = {
  blue: "text-[#0b73ff] bg-[rgba(11,115,255,0.09)] border-[rgba(11,115,255,0.16)]",
  orange: "text-[#f97316] bg-[rgba(249,115,22,0.09)] border-[rgba(249,115,22,0.16)]",
  red: "text-[#ef4444] bg-[rgba(239,68,68,0.09)] border-[rgba(239,68,68,0.16)]",
  violet: "text-[#8b5cf6] bg-[rgba(139,92,246,0.09)] border-[rgba(139,92,246,0.16)]",
};

const iconClass = computed(() => TONE[props.tone]);
</script>
