<template>
  <F7Sheet
    :opened="opened"
    swipe-to-close
    backdrop
    class="!h-auto !rounded-t-3xl"
    @sheet:closed="emit('update:opened', false)"
  >
    <div v-if="detail" class="relative max-h-[82vh] overflow-y-auto px-5 pt-5 pb-10">
      <button
        class="absolute right-4 top-4 z-10 flex h-8 w-8 items-center justify-center rounded-full bg-black/5 p-1"
        @click="emit('update:opened', false)"
      >
        <ILucideX class="h-5 w-5 text-gray-400" />
      </button>
      <div class="flex items-start gap-4 pr-8">
        <div
          :class="[
            'flex h-16 w-16 flex-shrink-0 items-center justify-center rounded-2xl',
            MEDIA_BG[detail.health],
          ]"
        >
          <ILucidePackage class="h-7 w-7" />
        </div>
        <div class="min-w-0 flex-1">
          <h2 class="text-xl font-bold leading-tight text-[#090e24]">{{ detail.name }}</h2>
          <div class="mt-1 flex items-center gap-2">
            <span class="text-xs text-gray-400">{{ detail.sku ?? "—" }}</span>
            <span v-if="detail.category" class="text-xs text-gray-300">·</span>
            <span v-if="detail.category" class="text-xs text-gray-400">{{ detail.category }}</span>
            <F7Chip :class="['ml-auto !text-xs !font-semibold', CHIP_COLOR[detail.health]]">
              {{ HEALTH_META[detail.health].label }}
            </F7Chip>
          </div>
        </div>
      </div>

      <div class="mt-5 grid grid-cols-4 gap-2">
        <div
          v-for="stat in stats"
          :key="stat.label"
          class="rounded-xl border border-[rgba(219,228,244,0.8)] bg-white/70 py-2.5 text-center shadow-[0_4px_12px_rgba(39,66,112,0.06)]"
        >
          <p class="text-lg font-bold text-[#090e24]">{{ stat.value }}</p>
          <p class="mt-0.5 text-[10px] text-gray-400">{{ stat.label }}</p>
        </div>
      </div>

      <div class="mt-5">
        <div class="mb-3 flex items-center gap-2">
          <ILucideMapPin class="h-4 w-4 text-[#0b73ff]" />
          <span class="text-xs font-semibold uppercase tracking-wide text-gray-400">Locations</span>
        </div>
        <div class="space-y-3">
          <div v-for="loc in detail.locations" :key="loc.name" class="flex items-center gap-3">
            <ILucideTruck v-if="loc.ratio === null" class="h-5 w-5 flex-shrink-0 text-gray-400" />
            <ILucideWarehouse v-else class="h-5 w-5 flex-shrink-0 text-gray-400" />
            <div class="min-w-0 flex-1">
              <div class="flex items-center justify-between">
                <span class="text-sm font-medium text-gray-700">{{ loc.name }}</span>
                <span class="text-xs font-semibold text-gray-500">
                  {{ loc.qty === null ? "—" : `${formatCompact(loc.qty)} units` }}
                </span>
              </div>
              <div class="mt-1 h-1.5 overflow-hidden rounded-full bg-gray-100">
                <div
                  class="h-full rounded-full"
                  :style="{
                    width: `${Math.round((loc.ratio ?? 0) * 100)}%`,
                    background: 'var(--f7-theme-color)',
                  }"
                />
              </div>
            </div>
          </div>
        </div>
      </div>

      <div class="mt-5">
        <div class="mb-2 flex items-center gap-2">
          <ILucideHistory class="h-4 w-4 text-gray-400" />
          <span class="text-xs font-semibold uppercase tracking-wide text-gray-400"
            >Recent movement</span
          >
        </div>
        <F7List
          v-if="detail.movements.length"
          class="!m-0 !rounded-2xl overflow-hidden border border-[rgba(219,228,244,0.8)]"
        >
          <F7ListItem
            v-for="m in detail.movements"
            :key="m.id"
            class="[--f7-list-item-padding-horizontal:12px]"
          >
            <template #media>
              <StockMovementIcon :kind="m.kind" :qty="m.qty" />
            </template>
            <template #title>
              <span class="capitalize text-sm font-medium text-gray-800">{{ m.kind }}</span>
            </template>
            <template #after>
              <span
                :class="['text-sm font-semibold', m.qty >= 0 ? 'text-green-600' : 'text-red-500']"
              >
                {{ m.qty >= 0 ? "+" : "" }}{{ m.qty }}
              </span>
            </template>
            <template #footer>
              <span class="text-xs text-gray-400">{{ formatTime(m.date) }}</span>
            </template>
          </F7ListItem>
        </F7List>
        <p v-else class="text-sm text-gray-400">No recent movement.</p>
      </div>

      <div class="mt-6 flex gap-3">
        <F7Button outline large class="flex-1" @click="emit('update:opened', false)">
          View full details
        </F7Button>
        <F7Button fill large class="flex-1" style="background: var(--f7-theme-color)">
          Adjust stock
        </F7Button>
      </div>
    </div>

    <div v-else class="flex items-center justify-center py-16">
      <F7Preloader />
    </div>
  </F7Sheet>
</template>

<script setup lang="ts">
import { toRef } from "vue";
import { useStockProduct } from "../composables/useStockProduct";
import { formatCompact, formatTime, HEALTH_META } from "../stock.format";
import StockMovementIcon from "./StockMovementIcon.vue";

const props = defineProps<{ productRuid: string | null; opened: boolean }>();
const emit = defineEmits<{ "update:opened": [value: boolean] }>();

const { detail } = useStockProduct(toRef(props, "productRuid"));

const CHIP_COLOR: Record<string, string> = {
  healthy: "!text-[#119d5a] !bg-[#dff8e9]",
  low: "!text-[#ff5b1a] !bg-[#fff0e6]",
  critical: "!text-[#e32727] !bg-[#ffe9ec]",
};

const MEDIA_BG: Record<string, string> = {
  critical: "text-red-400 bg-red-100/60",
  low: "text-amber-500 bg-amber-100/60",
  healthy: "text-blue-500 bg-blue-100/60",
};

const stats = computed(() => [
  { label: "On hand", value: formatCompact(detail.value?.onHand ?? 0) },
  { label: "Reorder at", value: String(detail.value?.reorderPoint ?? "—") },
  { label: "Reserved", value: formatCompact(detail.value?.reserved ?? 0) },
  { label: "Last sync", value: formatTime(detail.value?.lastSync ?? null) },
]);
</script>
